function mk(n: number, nan: boolean): number[] { const a: number[] = []; let s = 12345; for (let i = 0; i < n; i++) { s = (s * 1103515245 + 12345) % 2147483648; a.push((s % 1000) - 500); } a.push(Infinity, -Infinity, 0, -0, Infinity); if (nan) a.splice(7, 0, NaN); return a; }
function show(a: number[]): string { return a.slice(0, 12).map((x) => Object.is(x, -0) ? "-0" : String(x)).join(",") + "|" + a.slice(-6).join(","); }
function main(): void {
  const a = mk(300, false); a.sort((x, y) => x - y); console.log(show(a), a.length);
  const b = mk(300, false); b.sort((p, q) => q - p); console.log(show(b), b.length);
  const c = mk(300, false); const d = c.toSorted((m, n) => n - m); console.log(show(d), show(c));
  const e = mk(20, true); e.sort((x, y) => x - y); console.log(e.length, e.includes(NaN));
  const f = mk(20, false); f.sort((x, y) => x - y); console.log(show(f));
  const g = mk(300, false); g.sort((x, y) => y - x + 0); console.log(show(g));
}
